const tests = [
  { message: "Our website is down for all users.", category: "technical", priority: "high" },
  { message: "My profile picture is not uploading.", category: "technical", priority: "medium" },
  { message: "I was charged twice for my subscription.", category: "billing", priority: "medium" },
  { message: "My payment was declined.", category: "billing", priority: "medium" },
  { message: "How can I change my password?", category: "general", priority: "low" },
  { message: "Where can I find your opening hours?", category: "general", priority: "low" }
];

const runId = Date.now();

return tests.map((test, index) => ({
  json: {
    ticket_id: `EVAL-${runId}-${index}`,
    message: test.message,
    expected_category: test.category,
    expected_priority: test.priority
  }
}));

const tests = $('Test Cases').all();
const responses = $input.all();

let correctCategory = 0;
let correctPriority = 0;
let fullyCorrect = 0;
const failures = [];

for (const item of tests) {
  const test = item.json;
  const response = responses.find(
    r => r.json.body?.ticket_id === test.ticket_id
  )?.json;
  const actual = response?.body || {};

  const success = response?.statusCode === 200 && actual.status === "success";
  const categoryOK = success && actual.category === test.expected_category;
  const priorityOK = success && actual.priority === test.expected_priority;

  if (categoryOK) correctCategory++;
  if (priorityOK) correctPriority++;

  if (categoryOK && priorityOK) {
    fullyCorrect++;
  } else {
    failures.push({
      message: test.message,
      expected_category: test.expected_category,
      actual_category: actual.category || "missing",
      expected_priority: test.expected_priority,
      actual_priority: actual.priority || "missing"
    });
  }
}

const total = tests.length;

return [{
  json: {
    total_tests: total,
    category_accuracy: Math.round(correctCategory / total * 100),
    priority_accuracy: Math.round(correctPriority / total * 100),
    overall_accuracy: Math.round(fullyCorrect / total * 100),
    failures
  }
}];
